SELECT TEXT3
  FROM SCODE
 WHERE TYPE     = 'S000' 
   AND CODE     = ${CODE}
   AND LANGUAGE = ${LANGUAGE}


SELECT FLAG
     , TEXT5
  FROM SCODE
 WHERE TYPE     = 'S000' 
   AND CODE     = ${CODE}
   AND LANGUAGE = ${LANGUAGE}


SELECT TEXT4,TEXT3  
FROM SCODE
WHERE HOUSE_CODE = ${HOUSE_CODE}
  AND TYPE = ${TYPE}
  AND CODE = ${CODE}
  AND LANGUAGE = ${LANGUAGE}
